function jacobian_map_a_γo!(A_a_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_a_i[a] =- ωs[i] * 2 * γv[a] * λdago[i]
	end
end

function jacobian_map_a_γv!(A_a_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_vv = Matrix(I, nv, nv)
        λo = @view λ[1:no]
        λv = @view λ[(no+1):(no+nv)]
        λdago = @view λdag[1:no]
        λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_a_a[a] += ωs[b] * F_vv[a,b]
            A_a_a[a] += ωs[b] * 2 * γv[a] * λv[b]
            A_a_a[a] -= ωs[b] * F_ov[i,b] * t1s[a,i]
            A_a_a[a] += ωs[b] * t1s[c,i] * L_vvov[a,b,i,c]
            A_a_a[a] -= ωs[b] * L_ovov[i,b,j,c] * t2s[a,i,c,j]
            A_a_a[a] -= ωs[b] * t1s[a,i] * t1s[c,j] * L_ovov[i,b,j,c]
            A_a_a[a] += ωs[b] * 2 * δ_vv[a,b] * γv[c] * λv[c]
            A_a_a[a] -= ωs[b] * 2 * δ_vv[a,b] * γo[i] * λdago[i]
	end
end

function jacobian_map_a_t1s!(A_a_ai, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
           A_a_ai[a] += ωs[b,i] * γv[c] * L_vvov[a,c,i,b]
           A_a_ai[a] -= ωs[b,i] * γv[c] * t1s[a,j] * L_ovov[i,b,j,c]
           A_a_ai[a] += ωs[b,i] * δ_vv[a,b] * λdago[i]
           A_a_ai[a] -= ωs[b,i] * δ_vv[a,b] * γv[c] * F_ov[i,c]
           A_a_ai[a] -= ωs[b,i] * δ_vv[a,b] * γv[c] * t1s[d,j] * L_ovov[i,c,j,d]
	end
end

function jacobian_map_a_t2s!(A_a_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
           A_a_aibj[a] -= 1 // 2 * ωs[b,i,c,j] * δ_vv[a,b] * γv[d] * L_ovov[i,d,j,c]
           A_a_aibj[a] -= 1 // 2 * ωs[b,i,c,j] * δ_vv[a,c] * γv[d] * L_ovov[i,b,j,d]
	end
end

function jacobian_map_i_γo!(A_i_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
    A_i_i[i] =- ωs[j] * F_oo[j,i]
    A_i_i[i] -= ωs[j] * 2 * γo[i] * λdago[j]
    A_i_i[i] -= ωs[j] * F_ov[j,a] * t1s[a,i]
    A_i_i[i] -= ωs[j] * t1s[a,k] * L_ooov[j,i,k,a]
    A_i_i[i] -= ωs[j] * L_ovov[j,a,k,b] * t2s[a,i,b,k]
    A_i_i[i] -= ωs[j] * t1s[a,i] * t1s[b,k] * L_ovov[j,a,k,b]
    A_i_i[i] += ωs[j] * 2 * δ_oo[i,j] * γv[a] * λv[a]
    A_i_i[i] -= ωs[j] * 2 * δ_oo[i,j] * γo[k] * λdago[k]
	end
end

function jacobian_map_i_γv!(A_i_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
		A_i_a[i] += ωs[a] * 2 * γo[i] * λdagv[a]
	end
end

function jacobian_map_i_t1s!(A_i_ai, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
             A_i_ai[i] -= ωs[a,j] * γo[k] * L_ovoo[j,a,k,i]
             A_i_ai[i] -= ωs[a,j] * γo[k] * t1s[b,i] * L_ovov[j,a,k,b]
             A_i_ai[i] += ωs[a,j] * δ_oo[i,j] * λv[a]
             A_i_ai[i] -= ωs[a,j] * δ_oo[i,j] * γo[k] * F_ov[k,a]
             A_i_ai[i] -= ωs[a,j] * δ_oo[i,j] * γo[k] * t1s[b,l] * L_ovov[k,a,l,b]
	end
end

function jacobian_map_i_t2s!(A_i_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_i_aibj[i] -= 1 // 2 * ωs[a,j,b,k] * δ_oo[i,j] * γo[l] * L_ovov[k,b,l,a]
            A_i_aibj[i] -= 1 // 2 * ωs[a,j,b,k] * δ_oo[i,k] * γo[l] * L_ovov[j,a,l,b]
	end
end

function jacobian_map_ai_γo!(A_ai_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
	u = create_u(no, nv, t2s)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_ai_i[a,i] =  ωs[j] * γv[a] * F_oo[j,i]
            A_ai_i[a,i] += ωs[j] * γv[a] * F_ov[j,b] * t1s[b,i]
            A_ai_i[a,i] += ωs[j] * γv[a] * t1s[b,k] * L_ooov[j,i,k,b]
            A_ai_i[a,i] += ωs[j] * γv[a] * L_ovov[j,b,k,c] * t2s[b,i,c,k]
            A_ai_i[a,i] += ωs[j] * γv[a] * t1s[b,i] * t1s[c,k] * L_ovov[j,b,k,c]
            A_ai_i[a,i] += ωs[j] * δ_oo[i,j] * γv[b] * F_vv[a,b]
            A_ai_i[a,i] -= ωs[j] * δ_oo[i,j] * γv[b] * F_ov[k,b] * t1s[a,k]
            A_ai_i[a,i] += ωs[j] * δ_oo[i,j] * γv[b] * t1s[c,k] * L_vvov[a,b,k,c]
            A_ai_i[a,i] -= ωs[j] * δ_oo[i,j] * γv[b] * L_ovov[k,b,l,c] * t2s[a,k,c,l]
            A_ai_i[a,i] -= ωs[j] * δ_oo[i,j] * γv[b] * t1s[a,k] * t1s[c,l] * L_ovov[k,b,l,c]

	end
end

function jacobian_map_ai_γv!(A_ai_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
	u = create_u(no, nv, t2s)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_ai_a[a,i] += ωs[b] * γo[i] * F_vv[a,b]
            A_ai_a[a,i] -= ωs[b] * γo[i] * F_ov[j,b] * t1s[a,j]
            A_ai_a[a,i] += ωs[b] * γo[i] * t1s[c,j] * L_vvov[a,b,j,c]
            A_ai_a[a,i] -= ωs[b] * γo[i] * L_ovov[j,b,k,c] * t2s[a,j,c,k]
            A_ai_a[a,i] -= ωs[b] * γo[i] * t1s[a,j] * t1s[c,k] * L_ovov[j,b,k,c]
            A_ai_a[a,i] += ωs[b] * δ_vv[a,b] * γo[j] * F_oo[j,i]
            A_ai_a[a,i] += ωs[b] * δ_vv[a,b] * γo[j] * F_ov[j,c] * t1s[c,i]
            A_ai_a[a,i] += ωs[b] * δ_vv[a,b] * γo[j] * t1s[c,k] * L_ooov[j,i,k,c]
            A_ai_a[a,i] += ωs[b] * δ_vv[a,b] * γo[j] * L_ovov[j,c,k,d] * t2s[c,i,d,k]
            A_ai_a[a,i] += ωs[b] * δ_vv[a,b] * γo[j] * t1s[c,i] * t1s[d,k] * L_ovov[j,c,k,d]

	end
end

function jacobian_map_ai_t1s!(A_ai_ai, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_vv = Matrix(I, nv, nv)
	δ_oo = Matrix(I, no, no)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_ai_ai[a,i] += ωs[b,j] * L_voov[a,i,j,b]
            A_ai_ai[a,i] -= ωs[b,j] * t1s[a,k] * L_ovoo[j,b,k,i]
            A_ai_ai[a,i] += ωs[b,j] * t1s[c,i] * L_vvov[a,c,j,b]
            A_ai_ai[a,i] += ωs[b,j] * L_ovov[j,b,k,c] * u[a,i,c,k]
            A_ai_ai[a,i] += ωs[b,j] * γv[a] * γo[k] * L_ovoo[j,b,k,i]
            A_ai_ai[a,i] += ωs[b,j] * γo[i] * γv[c] * L_vvov[a,c,j,b]
            A_ai_ai[a,i] -= ωs[b,j] * t1s[a,k] * t1s[c,i] * L_ovov[j,b,k,c]
            A_ai_ai[a,i] += ωs[b,j] * γv[a] * γo[k] * t1s[c,i] * L_ovov[j,b,k,c]
            A_ai_ai[a,i] -= ωs[b,j] * γo[i] * γv[c] * t1s[a,k] * L_ovov[j,b,k,c]
            A_ai_ai[a,i] -= ωs[b,j] * δ_vv[a,b] * F_oo[j,i]
            A_ai_ai[a,i] += ωs[b,j] * δ_oo[i,j] * F_vv[a,b]
            A_ai_ai[a,i] -= ωs[b,j] * δ_vv[a,b] * F_ov[j,c] * t1s[c,i]
            A_ai_ai[a,i] -= ωs[b,j] * δ_oo[i,j] * F_ov[k,b] * t1s[a,k]
            A_ai_ai[a,i] -= ωs[b,j] * δ_vv[a,b] * t1s[c,k] * L_ooov[j,i,k,c]
            A_ai_ai[a,i] += ωs[b,j] * δ_oo[i,j] * t1s[c,k] * L_vvov[a,b,k,c]
            A_ai_ai[a,i] -= ωs[b,j] * δ_vv[a,b] * L_ovov[j,c,k,d] * t2s[c,i,d,k]
            A_ai_ai[a,i] -= ωs[b,j] * δ_oo[i,j] * L_ovov[k,b,l,c] * t2s[a,k,c,l]
            A_ai_ai[a,i] -= ωs[b,j] * δ_vv[a,b] * γo[i] * γv[c] * F_ov[j,c]
            A_ai_ai[a,i] += ωs[b,j] * δ_oo[i,j] * γv[a] * γo[k] * F_ov[k,b]
            A_ai_ai[a,i] -= ωs[b,j] * δ_vv[a,b] * t1s[c,i] * t1s[d,k] * L_ovov[j,c,k,d]
            A_ai_ai[a,i] -= ωs[b,j] * δ_oo[i,j] * t1s[a,k] * t1s[c,l] * L_ovov[k,b,l,c]
            A_ai_ai[a,i] -= ωs[b,j] * δ_vv[a,b] * γo[i] * γv[c] * t1s[d,k] * L_ovov[j,c,k,d]
            A_ai_ai[a,i] += ωs[b,j] * δ_oo[i,j] * γv[a] * γo[k] * t1s[c,l] * L_ovov[k,b,l,c]
	end
end

function jacobian_map_ai_t2s!(A_ai_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_vv = Matrix(I, nv, nv)
	δ_oo = Matrix(I, no, no)
        λo = @view λ[1:no]
        λv = @view λ[(no+1):(no+nv)]
        λdago = @view λdag[1:no]
        λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,b] * L_ooov[j,i,k,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,c] * L_ovoo[j,b,k,i]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * 1 // 2 * δ_oo[i,j] * L_vvov[a,b,k,c]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * 1 // 2 * δ_oo[i,k] * L_vvov[a,c,j,b]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,b] * t1s[d,i] * L_ovov[j,d,k,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,c] * t1s[d,i] * L_ovov[j,b,k,d]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_oo[i,j] * t1s[a,l] * L_ovov[l,b,k,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_oo[i,k] * t1s[a,l] * L_ovov[l,c,j,b]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,b] * γo[i] * γv[d] * L_ovov[j,d,k,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,c] * γo[i] * γv[d] * L_ovov[j,b,k,d]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * 1 // 2 * δ_oo[i,j] * γv[a] * γo[l] * L_ovov[l,b,k,c]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * 1 // 2 * δ_oo[i,k] * γv[a] * γo[l] * L_ovov[l,c,j,b]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * δ_vv[a,b] * δ_oo[i,j] * F_ov[k,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,b] * δ_oo[i,k] * F_ov[j,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,c] * δ_oo[i,j] * F_ov[k,b]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * δ_vv[a,c] * δ_oo[i,k] * F_ov[j,b]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * δ_vv[a,b] * δ_oo[i,j] * t1s[d,l] * L_ovov[l,d,k,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,b] * δ_oo[i,k] * t1s[d,l] * L_ovov[l,d,j,c]
    A_ai_aibj[a,i] -= ωs[b,j,c,k] * 1 // 2 * δ_vv[a,c] * δ_oo[i,j] * t1s[d,l] * L_ovov[l,d,k,b]
    A_ai_aibj[a,i] += ωs[b,j,c,k] * δ_vv[a,c] * δ_oo[i,k] * t1s[d,l] * L_ovov[l,d,j,b]
	end
end

function symmetric_sum!(no, nv, aibj)
	Ω2 = copy(aibj)
	@tensoropt aibj[a, i, b, j] += Ω2[b, j, a, i]
	aibj.*=0.5
end

function jacobian_map_aibj_γo!(A_aibj_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_aibj_i[a,i,b,j]  = ωs[k] * γv[a] * L_vooo[b,j,k,i]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * L_vooo[a,i,k,j]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * F_ov[k,c] * u[b,j,c,i]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * F_ov[k,c] * u[a,i,c,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * t1s[b,l] * L_oooo[k,i,l,j]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * t1s[c,i] * L_voov[b,j,k,c]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * t1s[c,j] * L_vvoo[b,c,k,i]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * t1s[a,l] * L_oooo[k,j,l,i]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * t1s[c,i] * L_vvoo[a,c,k,j]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * t1s[c,j] * L_voov[a,i,k,c]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * L_vvov[b,c,k,d] * t2s[c,j,d,i]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * L_ooov[k,j,l,c] * t2s[b,i,c,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * L_ovoo[k,c,l,j] * t2s[b,l,c,i]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * L_vvov[a,c,k,d] * t2s[c,i,d,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * L_ooov[k,i,l,c] * t2s[a,j,c,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * L_ovoo[k,c,l,i] * t2s[a,l,c,j]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * L_ooov[k,i,l,c] * u[b,j,c,l]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * L_ooov[k,j,l,c] * u[a,i,c,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * t1s[b,l] * t1s[c,i] * L_ovoo[k,c,l,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * t1s[b,l] * t1s[c,j] * L_ooov[k,i,l,c]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * t1s[c,i] * t1s[d,j] * L_vvov[b,d,k,c]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * t1s[a,l] * t1s[c,i] * L_ooov[k,j,l,c]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * t1s[a,l] * t1s[c,j] * L_ovoo[k,c,l,i]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * t1s[c,i] * t1s[d,j] * L_vvov[a,c,k,d]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * t1s[b,l] * L_ovov[k,c,l,d] * t2s[c,i,d,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * t1s[c,j] * L_ovov[k,c,l,d] * t2s[b,i,d,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * t1s[c,j] * L_ovov[k,d,l,c] * t2s[b,l,d,i]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * t1s[a,l] * L_ovov[k,c,l,d] * t2s[c,j,d,i]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * t1s[c,i] * L_ovov[k,c,l,d] * t2s[a,j,d,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * t1s[c,i] * L_ovov[k,d,l,c] * t2s[a,l,d,j]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * t1s[c,i] * L_ovov[k,c,l,d] * u[b,j,d,l]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[a] * t1s[c,l] * L_ovov[k,d,l,c] * u[b,j,d,i]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * t1s[c,j] * L_ovov[k,c,l,d] * u[a,i,d,l]
            A_aibj_i[a,i,b,j] += ωs[k] * γv[b] * t1s[c,l] * L_ovov[k,d,l,c] * u[a,i,d,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[a] * t1s[b,l] * t1s[c,i] * t1s[d,j] * L_ovov[k,c,l,d]
            A_aibj_i[a,i,b,j] -= ωs[k] * γv[b] * t1s[a,l] * t1s[c,i] * t1s[d,j] * L_ovov[k,d,l,c]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * L_vvvo[a,c,b,j]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * L_vovv[a,i,b,c]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * F_ov[l,c] * u[a,l,b,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * F_ov[l,c] * u[a,i,b,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * t1s[a,l] * L_voov[b,j,l,c]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * t1s[b,l] * L_vvoo[a,c,l,j]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * t1s[d,j] * L_vvvv[a,c,b,d]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * t1s[a,l] * L_vvoo[b,c,l,i]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * t1s[b,l] * L_voov[a,i,l,c]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * t1s[d,i] * L_vvvv[a,d,b,c]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * L_vvov[b,c,l,d] * t2s[a,j,d,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * L_vvov[b,d,l,c] * t2s[a,l,d,j]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * L_ooov[l,j,m,c] * t2s[a,m,b,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * L_vvov[a,c,l,d] * t2s[b,i,d,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * L_vvov[a,d,l,c] * t2s[b,l,d,i]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * L_ooov[l,i,m,c] * t2s[a,l,b,m]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * L_vvov[a,c,l,d] * u[b,j,d,l]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * L_vvov[b,c,l,d] * u[a,i,d,l]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * t1s[a,l] * t1s[b,m] * L_ovoo[l,c,m,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * t1s[a,l] * t1s[d,j] * L_vvov[b,d,l,c]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * t1s[b,l] * t1s[d,j] * L_vvov[a,c,l,d]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * t1s[a,l] * t1s[b,m] * L_ooov[l,i,m,c]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * t1s[a,l] * t1s[d,i] * L_vvov[b,c,l,d]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * t1s[b,l] * t1s[d,i] * L_vvov[a,d,l,c]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * t1s[b,l] * L_ovov[l,c,m,d] * t2s[a,j,d,m]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * t1s[b,l] * L_ovov[l,d,m,c] * t2s[a,m,d,j]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * t1s[d,j] * L_ovov[l,c,m,d] * t2s[a,l,b,m]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * t1s[a,l] * L_ovov[l,c,m,d] * t2s[b,i,d,m]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * t1s[a,l] * L_ovov[l,d,m,c] * t2s[b,m,d,i]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * t1s[d,i] * L_ovov[l,c,m,d] * t2s[a,m,b,l]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * t1s[a,l] * L_ovov[l,c,m,d] * u[b,j,d,m]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[i,k] * γv[c] * t1s[d,l] * L_ovov[l,d,m,c] * u[a,m,b,j]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * t1s[b,l] * L_ovov[l,c,m,d] * u[a,i,d,m]
            A_aibj_i[a,i,b,j] -= ωs[k] * δ_oo[j,k] * γv[c] * t1s[d,l] * L_ovov[l,d,m,c] * u[a,i,b,m]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[i,k] * γv[c] * t1s[a,l] * t1s[b,m] * t1s[d,j] * L_ovov[l,c,m,d]
            A_aibj_i[a,i,b,j] += ωs[k] * δ_oo[j,k] * γv[c] * t1s[a,l] * t1s[b,m] * t1s[d,i] * L_ovov[l,d,m,c]
	end
	#symmetric_sum!(no, nv, A_aibj_i)
end

function jacobian_map_aibj_γv!(A_aibj_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * L_vvvo[a,c,b,j]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * L_vovv[a,i,b,c]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * F_ov[k,c] * u[a,k,b,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * F_ov[k,c] * u[a,i,b,k]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * t1s[a,k] * L_voov[b,j,k,c]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * t1s[b,k] * L_vvoo[a,c,k,j]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * t1s[d,j] * L_vvvv[a,c,b,d]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * t1s[a,k] * L_vvoo[b,c,k,i]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * t1s[b,k] * L_voov[a,i,k,c]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * t1s[d,i] * L_vvvv[a,d,b,c]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * L_vvov[b,c,k,d] * t2s[a,j,d,k]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * L_vvov[b,d,k,c] * t2s[a,k,d,j]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * L_ooov[k,j,l,c] * t2s[a,l,b,k]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * L_vvov[a,c,k,d] * t2s[b,i,d,k]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * L_vvov[a,d,k,c] * t2s[b,k,d,i]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * L_ooov[k,i,l,c] * t2s[a,k,b,l]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * L_vvov[a,c,k,d] * u[b,j,d,k]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * L_vvov[b,c,k,d] * u[a,i,d,k]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * t1s[a,k] * t1s[b,l] * L_ovoo[k,c,l,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * t1s[a,k] * t1s[d,j] * L_vvov[b,d,k,c]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * t1s[b,k] * t1s[d,j] * L_vvov[a,c,k,d]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * t1s[a,k] * t1s[b,l] * L_ooov[k,i,l,c]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * t1s[a,k] * t1s[d,i] * L_vvov[b,c,k,d]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * t1s[b,k] * t1s[d,i] * L_vvov[a,d,k,c]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * t1s[b,k] * L_ovov[k,c,l,d] * t2s[a,j,d,l]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * t1s[b,k] * L_ovov[k,d,l,c] * t2s[a,l,d,j]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * t1s[d,j] * L_ovov[k,c,l,d] * t2s[a,k,b,l]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * t1s[a,k] * L_ovov[k,c,l,d] * t2s[b,i,d,l]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * t1s[a,k] * L_ovov[k,d,l,c] * t2s[b,l,d,i]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * t1s[d,i] * L_ovov[k,c,l,d] * t2s[a,l,b,k]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * t1s[a,k] * L_ovov[k,c,l,d] * u[b,j,d,l]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[i] * t1s[d,k] * L_ovov[k,d,l,c] * u[a,l,b,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * t1s[b,k] * L_ovov[k,c,l,d] * u[a,i,d,l]
            A_aibj_a[a,i,b,j] -= ωs[c] * γo[j] * t1s[d,k] * L_ovov[k,d,l,c] * u[a,i,b,l]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[i] * t1s[a,k] * t1s[b,l] * t1s[d,j] * L_ovov[k,c,l,d]
            A_aibj_a[a,i,b,j] += ωs[c] * γo[j] * t1s[a,k] * t1s[b,l] * t1s[d,i] * L_ovov[k,d,l,c]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * L_vooo[b,j,k,i]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * L_vooo[a,i,k,j]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * F_ov[k,d] * u[b,j,d,i]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * F_ov[k,d] * u[a,i,d,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * t1s[b,l] * L_oooo[k,i,l,j]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * t1s[d,i] * L_voov[b,j,k,d]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * t1s[d,j] * L_vvoo[b,d,k,i]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * t1s[a,l] * L_oooo[k,j,l,i]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * t1s[d,i] * L_vvoo[a,d,k,j]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * t1s[d,j] * L_voov[a,i,k,d]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * L_vvov[b,d,k,e] * t2s[d,j,e,i]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * L_ooov[k,j,l,d] * t2s[b,i,d,l]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * L_ovoo[k,d,l,j] * t2s[b,l,d,i]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * L_vvov[a,d,k,e] * t2s[d,i,e,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * L_ooov[k,i,l,d] * t2s[a,j,d,l]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * L_ovoo[k,d,l,i] * t2s[a,l,d,j]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * L_ooov[k,i,l,d] * u[b,j,d,l]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * L_ooov[k,j,l,d] * u[a,i,d,l]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * t1s[b,l] * t1s[d,i] * L_ovoo[k,d,l,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * t1s[b,l] * t1s[d,j] * L_ooov[k,i,l,d]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * t1s[d,i] * t1s[e,j] * L_vvov[b,e,k,d]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * t1s[a,l] * t1s[d,i] * L_ooov[k,j,l,d]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * t1s[a,l] * t1s[d,j] * L_ovoo[k,d,l,i]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * t1s[d,i] * t1s[e,j] * L_vvov[a,d,k,e]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * t1s[b,l] * L_ovov[k,d,l,e] * t2s[d,i,e,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * t1s[d,j] * L_ovov[k,d,l,e] * t2s[b,i,e,l]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * t1s[d,j] * L_ovov[k,e,l,d] * t2s[b,l,e,i]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * t1s[a,l] * L_ovov[k,d,l,e] * t2s[d,j,e,i]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * t1s[d,i] * L_ovov[k,d,l,e] * t2s[a,j,e,l]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * t1s[d,i] * L_ovov[k,e,l,d] * t2s[a,l,e,j]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * t1s[d,i] * L_ovov[k,d,l,e] * u[b,j,e,l]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[a,c] * γo[k] * t1s[d,l] * L_ovov[k,e,l,d] * u[b,j,e,i]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * t1s[d,j] * L_ovov[k,d,l,e] * u[a,i,e,l]
            A_aibj_a[a,i,b,j] += ωs[c] * δ_vv[b,c] * γo[k] * t1s[d,l] * L_ovov[k,e,l,d] * u[a,i,e,j]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[a,c] * γo[k] * t1s[b,l] * t1s[d,i] * t1s[e,j] * L_ovov[k,d,l,e]
            A_aibj_a[a,i,b,j] -= ωs[c] * δ_vv[b,c] * γo[k] * t1s[a,l] * t1s[d,i] * t1s[e,j] * L_ovov[k,e,l,d]
	end
	#symmetric_sum!(no, nv, A_aibj_a)
end

function jacobian_map_aibj_t1s!(A_aibj_ai, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            A_aibj_ai[a,i,b,j] += ωs[c,k] * L_vvov[a,d,k,c] * u[b,j,d,i]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * L_vvov[b,d,k,c] * u[a,i,d,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * L_ovoo[k,c,l,i] * u[a,l,b,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * L_ovoo[k,c,l,j] * u[a,i,b,l]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * t1s[a,l] * L_ovov[k,c,l,d] * u[b,j,d,i]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * t1s[b,l] * L_ovov[k,c,l,d] * u[a,i,d,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * t1s[d,i] * L_ovov[k,c,l,d] * u[a,l,b,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * t1s[d,j] * L_ovov[k,c,l,d] * u[a,i,b,l]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * γv[a] * γo[l] * L_ovov[k,c,l,d] * u[b,j,d,i]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * γo[i] * γv[d] * L_ovov[k,c,l,d] * u[a,l,b,j]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * γv[b] * γo[l] * L_ovov[k,c,l,d] * u[a,i,d,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * γo[j] * γv[d] * L_ovov[k,c,l,d] * u[a,i,b,l]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * L_vooo[b,j,k,i]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[i,k] * L_vvvo[a,c,b,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[b,c] * L_vooo[a,i,k,j]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * L_vovv[a,i,b,c]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * F_ov[k,d] * u[b,j,d,i]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[i,k] * F_ov[l,c] * u[a,l,b,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[b,c] * F_ov[k,d] * u[a,i,d,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * F_ov[l,c] * u[a,i,b,l]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[a,c] * t1s[b,l] * L_oooo[k,i,l,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * t1s[d,i] * L_voov[b,j,k,d]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * t1s[d,j] * L_vvoo[b,d,k,i]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[i,k] * t1s[a,l] * L_voov[b,j,l,c]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[i,k] * t1s[b,l] * L_vvoo[a,c,l,j]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[i,k] * t1s[d,j] * L_vvvv[a,c,b,d]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[b,c] * t1s[a,l] * L_oooo[k,j,l,i]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[b,c] * t1s[d,i] * L_vvoo[a,d,k,j]
