            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * t1s[a,l] * L_vvoo[b,c,l,i]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * t1s[b,l] * L_voov[a,i,l,c]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * t1s[d,i] * L_vvvv[a,d,b,c]
