            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * γo[i] * γv[d] * L_voov[b,j,k,d]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * γv[b] * γo[l] * L_oooo[k,i,l,j]
