            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * γv[a] * γo[l] * t1s[d,i] * L_vvov[b,c,l,d]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * γo[i] * γv[d] * t1s[a,l] * L_vvov[b,c,l,d]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * γo[i] * γv[d] * t1s[b,l] * L_vvov[a,d,l,c]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * γv[b] * γo[l] * t1s[a,m] * L_ovoo[l,c,m,i]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * γv[b] * γo[l] * t1s[d,i] * L_vvov[a,d,l,c]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * γv[b] * γo[l] * L_ovov[k,d,l,e] * t2s[d,i,e,j]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[a,c] * γo[j] * γv[d] * L_ovov[k,d,l,e] * t2s[b,i,e,l]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[a,c] * γo[j] * γv[d] * L_ovov[k,e,l,d] * t2s[b,l,e,i]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[i,k] * γv[b] * γo[l] * L_ovov[l,c,m,d] * t2s[a,j,d,m]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[i,k] * γv[b] * γo[l] * L_ovov[l,d,m,c] * t2s[a,m,d,j]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[i,k] * γo[j] * γv[d] * L_ovov[l,c,m,d] * t2s[a,l,b,m]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[b,c] * γv[a] * γo[l] * L_ovov[k,d,l,e] * t2s[d,j,e,i]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[b,c] * γo[i] * γv[d] * L_ovov[k,d,l,e] * t2s[a,j,e,l]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[b,c] * γo[i] * γv[d] * L_ovov[k,e,l,d] * t2s[a,l,e,j]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * γv[a] * γo[l] * L_ovov[l,c,m,d] * t2s[b,i,d,m]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * γv[a] * γo[l] * L_ovov[l,d,m,c] * t2s[b,m,d,i]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * γo[i] * γv[d] * L_ovov[l,c,m,d] * t2s[a,m,b,l]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * γo[i] * γv[d] * L_ovov[k,d,l,e] * u[b,j,e,l]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[i,k] * γv[a] * γo[l] * L_ovov[l,c,m,d] * u[b,j,d,m]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[b,c] * γo[j] * γv[d] * L_ovov[k,d,l,e] * u[a,i,e,l]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * γv[b] * γo[l] * L_ovov[l,c,m,d] * u[a,i,d,m]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[a,c] * t1s[b,l] * t1s[d,i] * t1s[e,j] * L_ovov[k,d,l,e]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[i,k] * t1s[a,l] * t1s[b,m] * t1s[d,j] * L_ovov[l,c,m,d]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[b,c] * t1s[a,l] * t1s[d,i] * t1s[e,j] * L_ovov[k,e,l,d]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * t1s[a,l] * t1s[b,m] * t1s[d,i] * L_ovov[l,d,m,c]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[a,c] * γo[i] * γv[d] * t1s[b,l] * t1s[e,j] * L_ovov[k,d,l,e]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[a,c] * γv[b] * γo[l] * t1s[d,i] * t1s[e,j] * L_ovov[k,d,l,e]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[a,c] * γo[j] * γv[d] * t1s[b,l] * t1s[e,i] * L_ovov[k,e,l,d]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[i,k] * γv[a] * γo[l] * t1s[b,m] * t1s[d,j] * L_ovov[l,c,m,d]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[i,k] * γv[b] * γo[l] * t1s[a,m] * t1s[d,j] * L_ovov[l,d,m,c]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[i,k] * γo[j] * γv[d] * t1s[a,l] * t1s[b,m] * L_ovov[l,c,m,d]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_vv[b,c] * γv[a] * γo[l] * t1s[d,i] * t1s[e,j] * L_ovov[k,e,l,d]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[b,c] * γo[i] * γv[d] * t1s[a,l] * t1s[e,j] * L_ovov[k,e,l,d]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_vv[b,c] * γo[j] * γv[d] * t1s[a,l] * t1s[e,i] * L_ovov[k,d,l,e]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * γv[a] * γo[l] * t1s[b,m] * t1s[d,i] * L_ovov[l,d,m,c]
            A_aibj_ai[a,i,b,j] += ωs[c,k] * δ_oo[j,k] * γo[i] * γv[d] * t1s[a,l] * t1s[b,m] * L_ovov[l,d,m,c]
            A_aibj_ai[a,i,b,j] -= ωs[c,k] * δ_oo[j,k] * γv[b] * γo[l] * t1s[a,m] * t1s[d,i] * L_ovov[l,c,m,d]
	end
	#symmetric_sum!(no, nv, A_aibj_ai)
end


function jacobian_map_aibj_t2s!(A_aibj_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)	
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * L_ovov[k,e,l,d] * u[b,j,e,i]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * L_ovov[k,c,l,e] * u[b,j,e,i]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * L_ovov[l,d,m,c] * u[a,m,b,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * L_ovov[k,c,m,d] * u[a,m,b,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[b,c] * L_ovov[k,e,l,d] * u[a,i,e,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[b,d] * L_ovov[k,c,l,e] * u[a,i,e,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[j,k] * L_ovov[l,d,m,c] * u[a,i,b,m]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[j,l] * L_ovov[k,c,m,d] * u[a,i,b,m]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[a,c] * δ_oo[i,k] * L_voov[b,j,l,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[i,l] * L_voov[b,j,k,d]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_vv[b,d] * L_oooo[k,i,l,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[j,k] * L_voov[b,i,l,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[j,l] * L_vvoo[b,d,k,i]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * L_voov[b,j,l,c]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * L_voov[b,j,k,c]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_vv[b,c] * L_oooo[k,j,l,i]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[j,k] * L_vvoo[b,c,l,i]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[j,l] * L_voov[b,i,k,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,c] * L_voov[a,j,l,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,d] * L_vvoo[a,c,l,j]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_oo[j,l] * L_vvvv[a,c,b,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,c] * L_vvoo[a,d,k,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,d] * L_voov[a,j,k,c]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_oo[j,k] * L_vvvv[a,d,b,c]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[b,c] * δ_oo[j,k] * L_voov[a,i,l,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[b,c] * δ_oo[j,l] * L_voov[a,i,k,d]
