    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[j,l] * t1s[b,m] * L_ooov[k,i,m,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[j,l] * t1s[e,i] * L_vvov[b,d,k,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * t1s[b,m] * L_ovoo[l,c,m,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * t1s[e,j] * L_vvov[b,e,l,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * t1s[b,m] * L_ovoo[k,c,m,j]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * t1s[e,j] * L_vvov[b,e,k,c]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_vv[b,c] * t1s[e,i] * L_ooov[k,j,l,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_vv[b,c] * t1s[e,j] * L_ovoo[k,e,l,i]
