    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[j,k] * t1s[e,i] * L_vvov[b,c,l,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[j,l] * t1s[b,m] * L_ovoo[k,c,m,i]
