    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,c] * t1s[a,m] * L_ovoo[l,d,m,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,c] * t1s[e,j] * L_vvov[a,e,l,d]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,d] * t1s[a,m] * L_ooov[l,j,m,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,d] * t1s[e,j] * L_vvov[a,c,l,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_oo[j,l] * t1s[a,m] * L_vvov[b,d,m,c]
