    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,c] * t1s[a,m] * L_ooov[k,j,m,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,c] * t1s[e,j] * L_vvov[a,d,k,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,d] * t1s[a,m] * L_ovoo[k,c,m,j]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,d] * t1s[e,j] * L_vvov[a,e,k,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_oo[j,k] * t1s[a,m] * L_vvov[b,c,m,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_oo[j,k] * t1s[b,m] * L_vvov[a,d,m,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[b,c] * δ_oo[j,k] * t1s[a,m] * L_ovoo[l,d,m,i]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[b,c] * δ_oo[j,k] * t1s[e,i] * L_vvov[a,e,l,d]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[b,c] * δ_oo[j,l] * t1s[a,m] * L_ovoo[k,d,m,i]
