    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[i,l] * δ_oo[j,k] * γv[b] * γo[m] * F_ov[m,d]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_vv[b,d] * δ_oo[j,k] * γo[i] * γv[e] * F_ov[l,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,c] * δ_vv[b,d] * δ_oo[j,l] * γo[i] * γv[e] * F_ov[k,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * δ_vv[b,c] * γo[j] * γv[e] * F_ov[l,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * δ_oo[j,l] * γv[b] * γo[m] * F_ov[m,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * δ_vv[b,c] * γo[j] * γv[e] * F_ov[k,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * δ_oo[j,k] * γv[b] * γo[m] * F_ov[m,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_vv[b,c] * δ_oo[j,k] * γo[i] * γv[e] * F_ov[l,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_vv[b,c] * δ_oo[j,l] * γo[i] * γv[e] * F_ov[k,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,c] * δ_oo[j,l] * γv[a] * γo[m] * F_ov[m,d]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_oo[i,k] * δ_vv[b,d] * δ_oo[j,l] * γv[a] * γo[m] * F_ov[m,c]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_oo[i,l] * δ_vv[b,c] * δ_oo[j,k] * γv[a] * γo[m] * F_ov[m,d]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,d] * δ_oo[j,k] * γv[a] * γo[m] * F_ov[m,c]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,c] * δ_oo[i,k] * δ_vv[b,d] * t1s[e,j] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,c] * δ_oo[i,k] * δ_oo[j,l] * t1s[b,m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[i,l] * δ_vv[b,d] * t1s[e,j] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[i,l] * δ_oo[j,k] * t1s[b,m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_vv[b,d] * δ_oo[j,k] * t1s[e,i] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,c] * δ_vv[b,d] * δ_oo[j,l] * t1s[e,i] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * δ_vv[b,c] * t1s[e,j] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * δ_oo[j,l] * t1s[b,m] * t1s[e,n] * L_ovov[m,c,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * δ_vv[b,c] * t1s[e,j] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * δ_oo[j,k] * t1s[b,m] * t1s[e,n] * L_ovov[m,c,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_vv[b,c] * δ_oo[j,k] * t1s[e,i] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_vv[b,c] * δ_oo[j,l] * t1s[e,i] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,c] * δ_oo[j,l] * t1s[a,m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_oo[i,k] * δ_vv[b,d] * δ_oo[j,l] * t1s[a,m] * t1s[e,n] * L_ovov[m,c,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_oo[i,l] * δ_vv[b,c] * δ_oo[j,k] * t1s[a,m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,d] * δ_oo[j,k] * t1s[a,m] * t1s[e,n] * L_ovov[m,c,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,c] * δ_oo[i,k] * δ_vv[b,d] * γo[j] * γv[e] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[a,c] * δ_oo[i,k] * δ_oo[j,l] * γv[b] * γo[m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[i,l] * δ_vv[b,d] * γo[j] * γv[e] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_oo[i,l] * δ_oo[j,k] * γv[b] * γo[m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,c] * δ_vv[b,d] * δ_oo[j,k] * γo[i] * γv[e] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,c] * δ_vv[b,d] * δ_oo[j,l] * γo[i] * γv[e] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * δ_vv[b,c] * γo[j] * γv[e] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * δ_oo[j,l] * γv[b] * γo[m] * t1s[e,n] * L_ovov[m,c,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * δ_vv[b,c] * γo[j] * γv[e] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_vv[a,d] * δ_oo[i,l] * δ_oo[j,k] * γv[b] * γo[m] * t1s[e,n] * L_ovov[m,c,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * δ_vv[a,d] * δ_vv[b,c] * δ_oo[j,k] * γo[i] * γv[e] * t1s[f,m] * L_ovov[l,e,m,f]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * 1 // 2 * δ_vv[a,d] * δ_vv[b,c] * δ_oo[j,l] * γo[i] * γv[e] * t1s[f,m] * L_ovov[k,e,m,f]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,k] * δ_vv[b,c] * δ_oo[j,l] * γv[a] * γo[m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_oo[i,k] * δ_vv[b,d] * δ_oo[j,l] * γv[a] * γo[m] * t1s[e,n] * L_ovov[m,c,n,e]
    A_aibj_aibj[a,i,b,j] += ωs[c,k,d,l] * δ_oo[i,l] * δ_vv[b,c] * δ_oo[j,k] * γv[a] * γo[m] * t1s[e,n] * L_ovov[m,d,n,e]
    A_aibj_aibj[a,i,b,j] -= ωs[c,k,d,l] * 1 // 2 * δ_oo[i,l] * δ_vv[b,d] * δ_oo[j,k] * γv[a] * γo[m] * t1s[e,n] * L_ovov[m,c,n,e]
	end
	#symmetric_sum!(no, nv, A_aibj_aibj)
end

function jacobianT_map_a_γo!(AT_a_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            AT_a_i[i] -= ωs[a] * 2 * γv[a] * λdago[i]
	end
end

function jacobianT_map_a_γv!(AT_a_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_vv = Matrix(I, nv, nv)
        λo = @view λ[1:no]
        λv = @view λ[(no+1):(no+nv)]
        λdago = @view λdag[1:no]
        λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            AT_a_a[b] += ωs[a] * F_vv[a,b]
            AT_a_a[b] += ωs[a] * 2 * γv[a] * λv[b]
            AT_a_a[b] -= ωs[a] * F_ov[i,b] * t1s[a,i]
            AT_a_a[b] += ωs[a] * t1s[c,i] * L_vvov[a,b,i,c]
            AT_a_a[b] -= ωs[a] * L_ovov[i,b,j,c] * t2s[a,i,c,j]
            AT_a_a[b] -= ωs[a] * t1s[a,i] * t1s[c,j] * L_ovov[i,b,j,c]
            AT_a_a[b] += ωs[a] * 2 * δ_vv[a,b] * γv[c] * λv[c]
            AT_a_a[b] -= ωs[a] * 2 * δ_vv[a,b] * γo[i] * λdago[i]
	end
end

function jacobianT_map_a_t1s!(AT_a_ai, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
           AT_a_ai[b,i] += ωs[a] * γv[c] * L_vvov[a,c,i,b]
           AT_a_ai[b,i] -= ωs[a] * γv[c] * t1s[a,j] * L_ovov[i,b,j,c]
           AT_a_ai[b,i] += ωs[a] * δ_vv[a,b] * λdago[i]
           AT_a_ai[b,i] -= ωs[a] * δ_vv[a,b] * γv[c] * F_ov[i,c]
           AT_a_ai[b,i] -= ωs[a] * δ_vv[a,b] * γv[c] * t1s[d,j] * L_ovov[i,c,j,d]
	end
end

function jacobianT_map_a_t2s!(AT_a_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
           AT_a_aibj[b,i,c,j] -= 1 // 2 * ωs[a] * δ_vv[a,b] * γv[d] * L_ovov[i,d,j,c]
           AT_a_aibj[b,i,c,j] -= 1 // 2 * ωs[a] * δ_vv[a,c] * γv[d] * L_ovov[i,b,j,d]
	end
end

function jacobianT_map_i_γo!(AT_i_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
    AT_i_i[j] -= ωs[i] * F_oo[j,i]
    AT_i_i[j] -= ωs[i] * 2 * γo[i] * λdago[j]
    AT_i_i[j] -= ωs[i] * F_ov[j,a] * t1s[a,i]
    AT_i_i[j] -= ωs[i] * t1s[a,k] * L_ooov[j,i,k,a]
    AT_i_i[j] -= ωs[i] * L_ovov[j,a,k,b] * t2s[a,i,b,k]
    AT_i_i[j] -= ωs[i] * t1s[a,i] * t1s[b,k] * L_ovov[j,a,k,b]
    AT_i_i[j] += ωs[i] * 2 * δ_oo[i,j] * γv[a] * λv[a]
    AT_i_i[j] -= ωs[i] * 2 * δ_oo[i,j] * γo[k] * λdago[k]
	end
end

function jacobianT_map_i_γv!(AT_i_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
		AT_i_a[a] += ωs[i] * 2 * γo[i] * λdagv[a]
	end
end

function jacobianT_map_i_t1s!(AT_i_ai, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
             AT_i_ai[a,j] -= ωs[i] * γo[k] * L_ovoo[j,a,k,i]
             AT_i_ai[a,j] -= ωs[i] * γo[k] * t1s[b,i] * L_ovov[j,a,k,b]
             AT_i_ai[a,j] += ωs[i] * δ_oo[i,j] * λv[a]
             AT_i_ai[a,j] -= ωs[i] * δ_oo[i,j] * γo[k] * F_ov[k,a]
             AT_i_ai[a,j] -= ωs[i] * δ_oo[i,j] * γo[k] * t1s[b,l] * L_ovov[k,a,l,b]
	end
end

function jacobianT_map_i_t2s!(AT_i_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            AT_i_aibj[a,j,b,k] -= 1 // 2 * ωs[i] * δ_oo[i,j] * γo[l] * L_ovov[k,b,l,a]
            AT_i_aibj[a,j,b,k] -= 1 // 2 * ωs[i] * δ_oo[i,k] * γo[l] * L_ovov[j,a,l,b]
	end
end

function jacobianT_map_ai_γo!(AT_ai_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
	u = create_u(no, nv, t2s)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            AT_ai_i[j] += ωs[a,i] * γv[a] * F_oo[j,i]
            AT_ai_i[j] += ωs[a,i] * γv[a] * F_ov[j,b] * t1s[b,i]
            AT_ai_i[j] += ωs[a,i] * γv[a] * t1s[b,k] * L_ooov[j,i,k,b]
            AT_ai_i[j] += ωs[a,i] * γv[a] * L_ovov[j,b,k,c] * t2s[b,i,c,k]
            AT_ai_i[j] += ωs[a,i] * γv[a] * t1s[b,i] * t1s[c,k] * L_ovov[j,b,k,c]
            AT_ai_i[j] += ωs[a,i] * δ_oo[i,j] * γv[b] * F_vv[a,b]
            AT_ai_i[j] -= ωs[a,i] * δ_oo[i,j] * γv[b] * F_ov[k,b] * t1s[a,k]
            AT_ai_i[j] += ωs[a,i] * δ_oo[i,j] * γv[b] * t1s[c,k] * L_vvov[a,b,k,c]
            AT_ai_i[j] -= ωs[a,i] * δ_oo[i,j] * γv[b] * L_ovov[k,b,l,c] * t2s[a,k,c,l]
            AT_ai_i[j] -= ωs[a,i] * δ_oo[i,j] * γv[b] * t1s[a,k] * t1s[c,l] * L_ovov[k,b,l,c]
	end
end

function jacobianT_map_ai_γv!(AT_ai_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
	u = create_u(no, nv, t2s)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            AT_ai_a[b] += ωs[a,i] * γo[i] * F_vv[a,b]
            AT_ai_a[b] -= ωs[a,i] * γo[i] * F_ov[j,b] * t1s[a,j]
            AT_ai_a[b] += ωs[a,i] * γo[i] * t1s[c,j] * L_vvov[a,b,j,c]
            AT_ai_a[b] -= ωs[a,i] * γo[i] * L_ovov[j,b,k,c] * t2s[a,j,c,k]
            AT_ai_a[b] -= ωs[a,i] * γo[i] * t1s[a,j] * t1s[c,k] * L_ovov[j,b,k,c]
            AT_ai_a[b] += ωs[a,i] * δ_vv[a,b] * γo[j] * F_oo[j,i]
            AT_ai_a[b] += ωs[a,i] * δ_vv[a,b] * γo[j] * F_ov[j,c] * t1s[c,i]
            AT_ai_a[b] += ωs[a,i] * δ_vv[a,b] * γo[j] * t1s[c,k] * L_ooov[j,i,k,c]
            AT_ai_a[b] += ωs[a,i] * δ_vv[a,b] * γo[j] * L_ovov[j,c,k,d] * t2s[c,i,d,k]
            AT_ai_a[b] += ωs[a,i] * δ_vv[a,b] * γo[j] * t1s[c,i] * t1s[d,k] * L_ovov[j,c,k,d]

	end
end

function jacobianT_map_ai_t1s!(AT_ai_ai, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_vv = Matrix(I, nv, nv)
	δ_oo = Matrix(I, no, no)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            AT_ai_ai[b,j] += ωs[a,i] * L_voov[a,i,j,b]
            AT_ai_ai[b,j] -= ωs[a,i] * t1s[a,k] * L_ovoo[j,b,k,i]
            AT_ai_ai[b,j] += ωs[a,i] * t1s[c,i] * L_vvov[a,c,j,b]
            AT_ai_ai[b,j] += ωs[a,i] * L_ovov[j,b,k,c] * u[a,i,c,k]
            AT_ai_ai[b,j] += ωs[a,i] * γv[a] * γo[k] * L_ovoo[j,b,k,i]
            AT_ai_ai[b,j] += ωs[a,i] * γo[i] * γv[c] * L_vvov[a,c,j,b]
            AT_ai_ai[b,j] -= ωs[a,i] * t1s[a,k] * t1s[c,i] * L_ovov[j,b,k,c]
            AT_ai_ai[b,j] += ωs[a,i] * γv[a] * γo[k] * t1s[c,i] * L_ovov[j,b,k,c]
            AT_ai_ai[b,j] -= ωs[a,i] * γo[i] * γv[c] * t1s[a,k] * L_ovov[j,b,k,c]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_vv[a,b] * F_oo[j,i]
            AT_ai_ai[b,j] += ωs[a,i] * δ_oo[i,j] * F_vv[a,b]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_vv[a,b] * F_ov[j,c] * t1s[c,i]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_oo[i,j] * F_ov[k,b] * t1s[a,k]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_vv[a,b] * t1s[c,k] * L_ooov[j,i,k,c]
            AT_ai_ai[b,j] += ωs[a,i] * δ_oo[i,j] * t1s[c,k] * L_vvov[a,b,k,c]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_vv[a,b] * L_ovov[j,c,k,d] * t2s[c,i,d,k]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_oo[i,j] * L_ovov[k,b,l,c] * t2s[a,k,c,l]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_vv[a,b] * γo[i] * γv[c] * F_ov[j,c]
            AT_ai_ai[b,j] += ωs[a,i] * δ_oo[i,j] * γv[a] * γo[k] * F_ov[k,b]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_vv[a,b] * t1s[c,i] * t1s[d,k] * L_ovov[j,c,k,d]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_oo[i,j] * t1s[a,k] * t1s[c,l] * L_ovov[k,b,l,c]
            AT_ai_ai[b,j] -= ωs[a,i] * δ_vv[a,b] * γo[i] * γv[c] * t1s[d,k] * L_ovov[j,c,k,d]
            AT_ai_ai[b,j] += ωs[a,i] * δ_oo[i,j] * γv[a] * γo[k] * t1s[c,l] * L_ovov[k,b,l,c]
	end
end

function jacobianT_map_ai_t2s!(AT_ai_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_vv = Matrix(I, nv, nv)
	δ_oo = Matrix(I, no, no)
        λo = @view λ[1:no]
        λv = @view λ[(no+1):(no+nv)]
        λdago = @view λdag[1:no]
        λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,b] * L_ooov[j,i,k,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,c] * L_ovoo[j,b,k,i]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * 1 // 2 * δ_oo[i,j] * L_vvov[a,b,k,c]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * 1 // 2 * δ_oo[i,k] * L_vvov[a,c,j,b]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,b] * t1s[d,i] * L_ovov[j,d,k,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,c] * t1s[d,i] * L_ovov[j,b,k,d]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_oo[i,j] * t1s[a,l] * L_ovov[l,b,k,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_oo[i,k] * t1s[a,l] * L_ovov[l,c,j,b]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,b] * γo[i] * γv[d] * L_ovov[j,d,k,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,c] * γo[i] * γv[d] * L_ovov[j,b,k,d]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * 1 // 2 * δ_oo[i,j] * γv[a] * γo[l] * L_ovov[l,b,k,c]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * 1 // 2 * δ_oo[i,k] * γv[a] * γo[l] * L_ovov[l,c,j,b]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * δ_vv[a,b] * δ_oo[i,j] * F_ov[k,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,b] * δ_oo[i,k] * F_ov[j,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,c] * δ_oo[i,j] * F_ov[k,b]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * δ_vv[a,c] * δ_oo[i,k] * F_ov[j,b]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * δ_vv[a,b] * δ_oo[i,j] * t1s[d,l] * L_ovov[l,d,k,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,b] * δ_oo[i,k] * t1s[d,l] * L_ovov[l,d,j,c]
    AT_ai_aibj[b,j,c,k] -= ωs[a,i] * 1 // 2 * δ_vv[a,c] * δ_oo[i,j] * t1s[d,l] * L_ovov[l,d,k,b]
    AT_ai_aibj[b,j,c,k] += ωs[a,i] * δ_vv[a,c] * δ_oo[i,k] * t1s[d,l] * L_ovov[l,d,j,b]
	end
end

function symmetric_sum!(no, nv, aibj)
	Ω2 = copy(aibj)
	@tensoropt aibj[a, i, b, j] += Ω2[b, j, a, i]
	aibj.*=0.5
end

function jacobianT_map_aibj_γo!(AT_aibj_i, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * L_vooo[b,j,k,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * L_vooo[a,i,k,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * F_ov[k,c] * u[b,j,c,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * F_ov[k,c] * u[a,i,c,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * t1s[b,l] * L_oooo[k,i,l,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * t1s[c,i] * L_voov[b,j,k,c]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * t1s[c,j] * L_vvoo[b,c,k,i]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * t1s[a,l] * L_oooo[k,j,l,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * t1s[c,i] * L_vvoo[a,c,k,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * t1s[c,j] * L_voov[a,i,k,c]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * L_vvov[b,c,k,d] * t2s[c,j,d,i]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * L_ooov[k,j,l,c] * t2s[b,i,c,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * L_ovoo[k,c,l,j] * t2s[b,l,c,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * L_vvov[a,c,k,d] * t2s[c,i,d,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * L_ooov[k,i,l,c] * t2s[a,j,c,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * L_ovoo[k,c,l,i] * t2s[a,l,c,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * L_ooov[k,i,l,c] * u[b,j,c,l]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * L_ooov[k,j,l,c] * u[a,i,c,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * t1s[b,l] * t1s[c,i] * L_ovoo[k,c,l,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * t1s[b,l] * t1s[c,j] * L_ooov[k,i,l,c]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * t1s[c,i] * t1s[d,j] * L_vvov[b,d,k,c]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * t1s[a,l] * t1s[c,i] * L_ooov[k,j,l,c]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * t1s[a,l] * t1s[c,j] * L_ovoo[k,c,l,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * t1s[c,i] * t1s[d,j] * L_vvov[a,c,k,d]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * t1s[b,l] * L_ovov[k,c,l,d] * t2s[c,i,d,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * t1s[c,j] * L_ovov[k,c,l,d] * t2s[b,i,d,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * t1s[c,j] * L_ovov[k,d,l,c] * t2s[b,l,d,i]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * t1s[a,l] * L_ovov[k,c,l,d] * t2s[c,j,d,i]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * t1s[c,i] * L_ovov[k,c,l,d] * t2s[a,j,d,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * t1s[c,i] * L_ovov[k,d,l,c] * t2s[a,l,d,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * t1s[c,i] * L_ovov[k,c,l,d] * u[b,j,d,l]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[a] * t1s[c,l] * L_ovov[k,d,l,c] * u[b,j,d,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * t1s[c,j] * L_ovov[k,c,l,d] * u[a,i,d,l]
            AT_aibj_i[k] += ωs[a,i,b,j] * γv[b] * t1s[c,l] * L_ovov[k,d,l,c] * u[a,i,d,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[a] * t1s[b,l] * t1s[c,i] * t1s[d,j] * L_ovov[k,c,l,d]
            AT_aibj_i[k] -= ωs[a,i,b,j] * γv[b] * t1s[a,l] * t1s[c,i] * t1s[d,j] * L_ovov[k,d,l,c]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * L_vvvo[a,c,b,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * L_vovv[a,i,b,c]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * F_ov[l,c] * u[a,l,b,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * F_ov[l,c] * u[a,i,b,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[a,l] * L_voov[b,j,l,c]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[b,l] * L_vvoo[a,c,l,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[d,j] * L_vvvv[a,c,b,d]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[a,l] * L_vvoo[b,c,l,i]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[b,l] * L_voov[a,i,l,c]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[d,i] * L_vvvv[a,d,b,c]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * L_vvov[b,c,l,d] * t2s[a,j,d,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * L_vvov[b,d,l,c] * t2s[a,l,d,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * L_ooov[l,j,m,c] * t2s[a,m,b,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * L_vvov[a,c,l,d] * t2s[b,i,d,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * L_vvov[a,d,l,c] * t2s[b,l,d,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * L_ooov[l,i,m,c] * t2s[a,l,b,m]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * L_vvov[a,c,l,d] * u[b,j,d,l]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * L_vvov[b,c,l,d] * u[a,i,d,l]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[a,l] * t1s[b,m] * L_ovoo[l,c,m,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[a,l] * t1s[d,j] * L_vvov[b,d,l,c]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[b,l] * t1s[d,j] * L_vvov[a,c,l,d]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[a,l] * t1s[b,m] * L_ooov[l,i,m,c]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[a,l] * t1s[d,i] * L_vvov[b,c,l,d]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[b,l] * t1s[d,i] * L_vvov[a,d,l,c]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[b,l] * L_ovov[l,c,m,d] * t2s[a,j,d,m]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[b,l] * L_ovov[l,d,m,c] * t2s[a,m,d,j]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[d,j] * L_ovov[l,c,m,d] * t2s[a,l,b,m]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[a,l] * L_ovov[l,c,m,d] * t2s[b,i,d,m]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[a,l] * L_ovov[l,d,m,c] * t2s[b,m,d,i]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[d,i] * L_ovov[l,c,m,d] * t2s[a,m,b,l]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[a,l] * L_ovov[l,c,m,d] * u[b,j,d,m]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[d,l] * L_ovov[l,d,m,c] * u[a,m,b,j]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[b,l] * L_ovov[l,c,m,d] * u[a,i,d,m]
            AT_aibj_i[k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[d,l] * L_ovov[l,d,m,c] * u[a,i,b,m]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[c] * t1s[a,l] * t1s[b,m] * t1s[d,j] * L_ovov[l,c,m,d]
            AT_aibj_i[k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[c] * t1s[a,l] * t1s[b,m] * t1s[d,i] * L_ovov[l,d,m,c]
	end
end

function jacobianT_map_aibj_γv!(AT_aibj_a, γo, γv, t1s, t2s, λ, λdag, ωs)
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
