            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[j,k] * t1s[b,l] * L_ovov[l,c,m,d] * u[a,i,d,m]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[j,k] * t1s[d,l] * L_ovov[l,d,m,c] * u[a,i,b,m]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[a,c] * γo[i] * γv[d] * t1s[b,l] * L_ovoo[k,d,l,j]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[a,c] * γo[i] * γv[d] * t1s[e,j] * L_vvov[b,e,k,d]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[a,c] * γv[b] * γo[l] * t1s[d,i] * L_ovoo[k,d,l,j]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[a,c] * γv[b] * γo[l] * t1s[d,j] * L_ooov[k,i,l,d]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[a,c] * γo[j] * γv[d] * t1s[b,l] * L_ooov[k,i,l,d]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[a,c] * γo[j] * γv[d] * t1s[e,i] * L_vvov[b,d,k,e]
