            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[a] * γo[l] * t1s[b,m] * L_ooov[l,i,m,c]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[a] * γo[l] * t1s[d,i] * L_vvov[b,c,l,d]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[j,k] * γo[i] * γv[d] * t1s[a,l] * L_vvov[b,c,l,d]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[j,k] * γo[i] * γv[d] * t1s[b,l] * L_vvov[a,d,l,c]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[b] * γo[l] * t1s[a,m] * L_ovoo[l,c,m,i]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[b] * γo[l] * t1s[d,i] * L_vvov[a,d,l,c]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[a,c] * γv[b] * γo[l] * L_ovov[k,d,l,e] * t2s[d,i,e,j]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[a,c] * γo[j] * γv[d] * L_ovov[k,d,l,e] * t2s[b,i,e,l]
