            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[b,c] * γv[a] * γo[l] * L_ovov[k,d,l,e] * t2s[d,j,e,i]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[b,c] * γo[i] * γv[d] * L_ovov[k,d,l,e] * t2s[a,j,e,l]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[b,c] * γo[i] * γv[d] * L_ovov[k,e,l,d] * t2s[a,l,e,j]
