            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[i,k] * γv[a] * γo[l] * L_ovov[l,c,m,d] * u[b,j,d,m]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[b,c] * γo[j] * γv[d] * L_ovov[k,d,l,e] * u[a,i,e,l]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[j,k] * γv[b] * γo[l] * L_ovov[l,c,m,d] * u[a,i,d,m]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[a,c] * t1s[b,l] * t1s[d,i] * t1s[e,j] * L_ovov[k,d,l,e]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[i,k] * t1s[a,l] * t1s[b,m] * t1s[d,j] * L_ovov[l,c,m,d]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[b,c] * t1s[a,l] * t1s[d,i] * t1s[e,j] * L_ovov[k,e,l,d]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[j,k] * t1s[a,l] * t1s[b,m] * t1s[d,i] * L_ovov[l,d,m,c]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[a,c] * γo[i] * γv[d] * t1s[b,l] * t1s[e,j] * L_ovov[k,d,l,e]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[a,c] * γv[b] * γo[l] * t1s[d,i] * t1s[e,j] * L_ovov[k,d,l,e]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[a,c] * γo[j] * γv[d] * t1s[b,l] * t1s[e,i] * L_ovov[k,e,l,d]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[i,k] * γv[a] * γo[l] * t1s[b,m] * t1s[d,j] * L_ovov[l,c,m,d]
