            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[i,k] * γo[j] * γv[d] * t1s[a,l] * t1s[b,m] * L_ovov[l,c,m,d]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_vv[b,c] * γv[a] * γo[l] * t1s[d,i] * t1s[e,j] * L_ovov[k,e,l,d]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[b,c] * γo[i] * γv[d] * t1s[a,l] * t1s[e,j] * L_ovov[k,e,l,d]
            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_vv[b,c] * γo[j] * γv[d] * t1s[a,l] * t1s[e,i] * L_ovov[k,d,l,e]
