            AT_aibj_ai[c,k] += ωs[a,i,b,j] * δ_oo[j,k] * γo[i] * γv[d] * t1s[a,l] * t1s[b,m] * L_ovov[l,d,m,c]
            AT_aibj_ai[c,k] -= ωs[a,i,b,j] * δ_oo[j,k] * γv[b] * γo[l] * t1s[a,m] * t1s[d,i] * L_ovov[l,c,m,d]
	end
end


function jacobianT_map_aibj_t2s!(AT_aibj_aibj, γo, γv, t1s, t2s, λ, λdag, ωs)	
	no = size(γo, 1)
	nv = size(γv, 1)
	u = create_u(no, nv, t2s)
	δ_oo = Matrix(I, no, no)
	δ_vv = Matrix(I, nv, nv)
   λo = @view λ[1:no]
   λv = @view λ[(no+1):(no+nv)]
   λdago = @view λdag[1:no]
   λdagv = @view λdag[(1+no):(no+nv)]
	@tensoropt begin
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[a,c] * L_ovov[k,e,l,d] * u[b,j,e,i]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[a,d] * L_ovov[k,c,l,e] * u[b,j,e,i]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_oo[i,k] * L_ovov[l,d,m,c] * u[a,m,b,j]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_oo[i,l] * L_ovov[k,c,m,d] * u[a,m,b,j]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[b,c] * L_ovov[k,e,l,d] * u[a,i,e,j]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[b,d] * L_ovov[k,c,l,e] * u[a,i,e,j]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_oo[j,k] * L_ovov[l,d,m,c] * u[a,i,b,m]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_oo[j,l] * L_ovov[k,c,m,d] * u[a,i,b,m]
    AT_aibj_aibj[c,k,d,l] += ωs[a,i,b,j] * δ_vv[a,c] * δ_oo[i,k] * L_voov[b,j,l,d]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[a,c] * δ_oo[i,l] * L_voov[b,j,k,d]
    AT_aibj_aibj[c,k,d,l] += ωs[a,i,b,j] * 1 // 2 * δ_vv[a,c] * δ_vv[b,d] * L_oooo[k,i,l,j]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[a,c] * δ_oo[j,k] * L_voov[b,i,l,d]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[a,c] * δ_oo[j,l] * L_vvoo[b,d,k,i]
    AT_aibj_aibj[c,k,d,l] -= ωs[a,i,b,j] * 1 // 2 * δ_vv[a,d] * δ_oo[i,k] * L_voov[b,j,l,c]
